pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

pm.test("Response contains users", function () {
    const data = pm.response.json();
    pm.expect(data.users).to.be.an("array");
    pm.expect(data.users.length).to.be.above(0);
});

pm.test("User ID is a number", function () {
    const data = pm.response.json();
    pm.expect(data.users[0].id).to.be.a("number");
});

pm.test("User email is a string", function () {
    const data = pm.response.json();
    pm.expect(data.users[0].email).to.be.a("string");
});

pm.test("User has required fields", function () {
    const user = pm.response.json().users[0];

    pm.expect(user).to.have.property("id");
    pm.expect(user).to.have.property("firstName");
    pm.expect(user).to.have.property("email");
});

pm.test("Status code is 201", function () {
    pm.response.to.have.status(201);
});

pm.test("Created user has correct first name", function () {
    const data = pm.response.json();
    pm.expect(data.firstName).to.eql("Sara");
});

pm.test("Created user has an ID", function () {
    const data = pm.response.json();
    pm.expect(data.id).to.exist;
});

pm.test("Status code is 404", function () {
    pm.response.to.have.status(404);
});

pm.test("Response contains an error message", function () {
    const data = pm.response.json();
    pm.expect(data.message).to.be.a("string");
    pm.expect(data.message.length).to.be.above(0);
});
